import { URLExt, ServerConnection } from '@jupyterlab/services';

export async function fetchBearBorgUrl(): Promise<string> {
  const serverSettings = ServerConnection.makeSettings();
  const requestUrl = URLExt.join(serverSettings.baseUrl, 'bearborg', 'config');

