import {
  JupyterFrontEnd,
  JupyterFrontEndPlugin
} from '@jupyterlab/application';


import { ICommandPalette, MainAreaWidget } from '@jupyterlab/apputils';

import { Widget } from '@lumino/widgets';

import { IMainMenu } from '@jupyterlab/mainmenu';

import { ILauncher } from '@jupyterlab/launcher';

import { LabIcon } from '@jupyterlab/ui-components';


import bearBorgIconSvg from '../style/icons/BearBorgIcon.svg';

import { PageConfig } from '@jupyterlab/coreutils';

const b1 =  PageConfig.getOption('bearborgUrl') 
console.log('PageConfig at load:', PageConfig);
console.log(b1)


// Append your path — trailing slash ensures default_filename works!
const bearBorgUrl = 
      PageConfig.getOption('bearborgUrl') || '/hub/bearborg/';


// Register the icon
export const bearBorgIcon = new LabIcon({
  name: 'bearborg-doc-extenstion:bearborg-icon',
  svgstr: bearBorgIconSvg
});




/**
 * Initialization data for the bearborg-doc-extension extension.
 */
const plugin: JupyterFrontEndPlugin<void> = {
  id: 'bearborg-help',
  description: 'Show the About BearBorg page JupyterLab panel.',
  autoStart: true,
  requires: [ICommandPalette, IMainMenu, ILauncher],
  activate: (app: JupyterFrontEnd, palette: ICommandPalette, mainMenu: IMainMenu, launcher: ILauncher) => {
    console.log('BearBorg help is activated');
    console.log(bearBorgUrl);

    // Define a widget creator function,
    // then call it to make a new widget
    const newWidget = () => {
      const content = new Widget();


      content.node.innerHTML = `
        <iframe
          src="${bearBorgUrl}"
          style="width: 100%; height: 100%; border: none;">
        </iframe>
      `;

      content.node.style.overflow = 'hidden';
      content.node.style.height = '100%';

      content.addClass('jp-About-content');

      const widget = new MainAreaWidget({ content });
      widget.id = 'bearborg-help';
      widget.title.label = 'About BearBorg';
      widget.title.closable = true;

      return widget;
    };

    let widget = newWidget();

    // Add an application command
    const command: string = 'bearborg-help:open';
    app.commands.addCommand(command, {
      label: 'About BearBorg',
      execute: () => {
        // Regenerate the widget if disposed
        if (widget.isDisposed) {
          widget = newWidget();
        }
        if (!widget.isAttached) {
          // Attach the widget to the main work area if it's not there
          app.shell.add(widget, 'main');
        }
        // Activate the widget
        app.shell.activateById(widget.id);
      },
      icon: bearBorgIcon
    });

    const helpMenu = mainMenu.helpMenu;
    helpMenu.addGroup(
      [
        {
          command: 'bearborg-help:open'
        }
      ],
      100  // Rank: adjust where it shows up in the list
    );

    launcher.add({
      command: 'bearborg-help:open',
      category: 'Other',  // Where it appears
      rank: 1,            // Order within the category
      // Optionally:
      // args: { ... },
    });


    // Add the command to the palette.
    palette.addItem({ command, category: 'Help' });
  }
};

export default plugin;

import os
from jupyter_server.base.handlers import APIHandler
from jupyter_server.utils import url_path_join
import tornado

'''
Send the BEARBORG_URL to the JupyterLab instance in response to <base>/bearborg/config
'''
class BearBorgConfigHandler(APIHandler):
    @tornado.web.authenticated
    def get(self):
        bearborg_url = os.environ.get("BEARBORG_URL", "/hub/bearborg/")
        self.finish({
            "bearborgUrl": bearborg_url
        })

def setup_handlers(web_app):
    host_pattern = ".*$"
    base_url = web_app.settings["base_url"]
    route_pattern = url_path_join(base_url, "bearborg", "config")
    handlers = [(route_pattern, BearBorgConfigHandler)]
    web_app.add_handlers(host_pattern, handlers)

def _jupyter_server_extension_points():
    return [{
        "module": "bearborg_doc_extension"  # or whatever our module name is
    }]

